def _run_animal(n: str, f: dict, peer, local,
                conversation: Optional[str] = None) -> Result:
    """Animal options by asking - the same functions the switches call, so
    the same rules: the shared switches and the sun and moon at once, the
    weather off or Home Assistant at once, Open-Meteo ONE approval card
    (jarvis_sky raises it; nothing changes until it is approved); sharpness
    and frame rate on the device that asked, named in X-Jarvis-Route.

    Every one of these is CARDLESS except Open-Meteo's card, so every one of
    them leaves the same ONE undo receipt a switch does (2026-11-03, the
    audit's BUG 6 - "a cardless change leaves one receipt" was false for
    exactly the settings this slice's headline names). The snapshot holds the
    VALUE each setter takes, read from the owning module's own table.
    """
    if n == "animal_ask":
        return Result(ANIMAL_QUESTIONS.get(f.get("about"), ANIMAL_QUESTIONS["animal"]), n)
    if n == "animal_device":
        try:
            import jarvis_animal as AN
            said = AN.DEVICE_SAID[f["change"]]
        except Exception:
            return Result(ANIMAL_MISSING, n)
        return Result(said, n, face_tuning=f["change"])
    try:
        import jarvis_settings_registry as R
    except Exception:
        return Result(SETTINGS_MISSING, n)
    if n == "animal_switch":
        key = str(f.get("key") or "")
        before = R.animal_switch_value(key)
        since = _newest_receipt_id()
        out = R.set_animal_switch(key, f["on"], peer=peer, local=local)
        if (getattr(out, "ok", False) and not getattr(out, "waiting", False)
                and before is not None and before != bool(f["on"])):
            label = R.animal_switch_label(key)
            _settings_receipt(
                conversation, None,
                {"kind": "animal_switch", "key": key, "value": before},
                {"kind": "animal_switch", "key": key, "value": bool(f["on"])},
                f"Turned {label} {'on' if f['on'] else 'off'}", since=since,
                label=label)
    elif n == "animal_sky":
        before = R.sky_show_value()
        since = _newest_receipt_id()
        out = R.set_sky_show(f["on"], peer=peer, local=local)
        if (getattr(out, "ok", False) and not getattr(out, "waiting", False)
                and before is not None and before != bool(f["on"])):
            label = "the sun and moon"
            _settings_receipt(
                conversation, None,
                {"kind": "sky_show", "key": "the sun and moon", "value": before},
                {"kind": "sky_show", "key": "the sun and moon",
                 "value": bool(f["on"])},
                f"Turned {label} {'on' if f['on'] else 'off'}", since=since,
                label=label)
    elif n == "animal_weather":
        source = str(f.get("source") or "")
        before = R.weather_source_id()
        since = _newest_receipt_id()
        out = R.set_weather_source(source, peer=peer, local=local)
        if getattr(out, "ok", False) and getattr(out, "waiting", False):
            # jarvis_sky's own two sentences, in one: the card is up and
            # nothing has changed (the card is the only yes - a spoken one
            # approves nothing).
            return Result("An approval card is up - nothing is sent to Open-Meteo until you "
                          "approve it, on your PC or phone.", n)
        if (getattr(out, "ok", False) and before and before != source):
            # THE VALUE, NOT THE WORDS: `set_weather_source` takes the id
            # ("home_assistant") while the answer prints the label.
            _settings_receipt(
                conversation, None,
                {"kind": "weather_source", "key": "the weather source",
                 "value": before},
                {"kind": "weather_source", "key": "the weather source",
                 "value": source},
                f"Set the weather source to {R.weather_source_label(source)}",
                since=since, label="the weather source")
    else:
        return Result(ANIMAL_QUESTIONS["animal"], "animal_ask")
    return Result(out.said, n)


ANIMAL_MISSING = ("Your PC's Jarvis does not have the animal options yet - run "
                  "apply-patches.ps1 on the PC.")


def _run_settings_tool(f: dict, peer, local,
                       conversation: Optional[str] = None,
                       live: bool = False) -> Result:
    """"Let the AI model use this" - whether a tool is offered to the
    model at all (jarvis_asks_first's [tools].enabled switch).

    The setter is the registry's own, which calls the module's route function:
    ON is the PC only, one card plus Windows Hello; OFF is instant. Since
    2026-11-03 a real change (in practice the instant OFF) leaves ONE undo
    receipt, with the before value read from the module that owns the list
    (`reading_tool_now`).

    `live` (2026-11-07) changes only the WORDING of a carded ON change's
    answer, exactly like `_settings_said` does for a switch: Live speaks the
    answer aloud, so a card waiting gets ONE calm line instead of the setter's
    card sentence. The card, the tier, the PC-only refusal and the value are
    all the setter's, unchanged."""
    import jarvis_settings_registry as R
    tool = str(f.get("tool") or "")
    on = bool(f.get("on"))
    before = R.reading_tool_now(tool)
    since = _newest_receipt_id()
    out = R.set_reading_tool(tool, on, peer=peer, local=local)
    if (getattr(out, "ok", False) and not getattr(out, "waiting", False)
            and before is not None):
        names = R.tool_targets().get(tool) or (tool,)
        label = f"offering {names[0]} to the AI model"
        _settings_receipt(
            conversation, None,
            {"kind": "reading_tool", "key": f"reading_tool:{tool}",
             "value": before},
            {"kind": "reading_tool", "key": f"reading_tool:{tool}", "value": on},
            f"{'Offered' if on else 'Stopped offering'} {names[0]} to the AI "
            f"model", since=since, label=label)
    if live and getattr(out, "waiting", False):
        return Result(_settings_tool_waiting_line(tool), "settings_tool")
    return Result(out.said, "settings_tool")


# --------------------------------------------------------------------------
#   Explaining a feature, its state and how to change it (2026-10-20) - no
#   model, no network: every word comes from jarvis_feature_guide, which reads
#   the owner's own feature list and the switch's owning module. Nothing here
#   guesses: the guide's own sentences say when it could not read a state.
# --------------------------------------------------------------------------

FEATURE_MISSING = ("Your PC's Jarvis does not have the feature list yet - run "
                   "apply-patches.ps1 on the PC.")


def _guide():
    try:
        import jarvis_feature_guide as FG
        return FG
    except Exception:
        return None


def _run_features_list(f: dict) -> Result:
    FG = _guide()
    if FG is None:
        return Result(FEATURE_MISSING, "features_list")
    return Result(FG.groups_words(), "features_list")


