def _settings_undone_recently(conversation, now: float) -> Optional[Result]:
    """The second "undo": the setting is already back, so say that and change
    nothing. None when this chat has not put a setting back recently."""
    key = str(conversation or "")
    entry = _SETTINGS_UNDONE.get(key)
    if not entry:
        return None
    try:
        import jarvis_schedule as S
        window = float(S.UNDO_WINDOW)
    except Exception:
        window = 600.0
    if float(now) - float(entry.get("at") or 0.0) > window:
        _SETTINGS_UNDONE.pop(key, None)
        return None
    label = str(entry.get("label") or "that setting")
    return Result(f"I already put {label} back in this chat, so there is nothing left to "
                  f"undo.", "undo")


def _run_settings_undo(conversation, peer=None, local=None) -> Optional[Result]:
    """Take back the newest CARDLESS settings change in this chat, ONCE.

    None means "this chat has no settings change to take back" - the caller then
    answers as it always did. The take is the receipts module's own `undo`,
    which claims the row with one conditional UPDATE, so even two callers at
    once cannot put the same change back twice. What it says afterwards is the
    SETTER's own sentence when the reversal reached it (the same words the owner
    would hear saying the change the other way), and an honest sentence
    otherwise - a setter's refusal quotes the setter, and only a real card that
    was not answered says the card thing (`_settings_undo_words`). A receipt
    whose reversal raises its own approval card is NOT reported as undone.

    A FAILED reversal keeps this chat's pointer (`_SETTINGS_UNDO`), so "undo"
    can be tried again and the receipt, which is still undoable in the store, is
    still reachable (2026-11-03 audit, BUG 4: the pointer used to be popped
    first, so the second "undo" said there was nothing to take back).

    `peer`/`local` are THIS request's own address, handed to the setter exactly
    as the change itself would hand them: a phone cannot put back a setting the
    PC only may change, and gets the setter's own refusal saying so.
    """
    key = str(conversation or "")
    entry = _SETTINGS_UNDO.get(key)
    if not entry:
        return None
    n = "undo"
    label = str(entry.get("label") or "that setting")
    # Clear what a PREVIOUS attempt said, so a failure that never reached the
    # setter cannot quote the last one's words.
    entry["said"] = {}
    _SETTINGS_UNDO_LAST.said = ""
    _SETTINGS_UNDO_LAST.waiting = False
    _SETTINGS_UNDO_CALLER.peer, _SETTINGS_UNDO_CALLER.local = peer, local
    try:
        import jarvis_receipts as RC
        out = RC.undo(str(entry.get("receipt_id") or ""))
    except Exception:
        return Result(_settings_undo_words(label, ""), n)
    finally:
        _SETTINGS_UNDO_CALLER.peer = _SETTINGS_UNDO_CALLER.local = None
    said = str((entry.get("said") or {}).get("said")
               or getattr(_SETTINGS_UNDO_LAST, "said", "") or "").strip()
    waiting = bool((entry.get("said") or {}).get("waiting")
                   or getattr(_SETTINGS_UNDO_LAST, "waiting", False))
    if out.get("ok"):
        _SETTINGS_UNDO.pop(key, None)
        _SETTINGS_UNDONE[key] = {"label": label, "at": time.time()}
        return Result(said or f"Put {label} back the way it was.", n)
    if out.get("already_undone"):
        _SETTINGS_UNDO.pop(key, None)
        _SETTINGS_UNDONE[key] = {"label": label, "at": time.time()}
        return Result(f"{label[:1].upper()}{label[1:]} was already back the way it was, so "
                      f"nothing was changed.", n)
    # NOT undone: keep the pointer so the next "undo" can try again.
    return Result(_settings_undo_words(label, said, waiting), n)


def _run_undo(f: dict, sched, now: float, conversation, peer=None,
              local=None) -> Optional[Result]:
    """"Cancel that": the last thing the fast path set in THIS conversation,
    within UNDO_WINDOW, once. Nothing else, ever.

    Since 2026-11-03 it also takes back the newest CARDLESS settings change made
    in this chat: a setting creates nothing in the scheduler, so it can never
    appear as the scheduler's own record - it keeps a receipt instead, and the
    registry has promised that undo since it was written. A scheduler record
    always wins, so "cancel that" after a reminder still cancels the reminder.
    `peer`/`local` are the request's own address, passed on to the setting's
    setter when a setting is what is being put back.
    """
    import jarvis_schedule as S
    n = "undo"
    noun = f.get("noun")
    rec = None
    try:
        rec = sched.last_set(conversation, now) if conversation else None
    except Exception:
        rec = None
    if rec is None and noun is None and not f.get("soft"):
        taken = _run_settings_undo(conversation, peer, local)
        if taken is not None:
            return taken
    fits = rec is not None and (noun is None or noun in (rec.get("nouns") or ()))
    if rec is None or not fits:
        # Nothing of ours to take back. "cancel that timer" / "... alarm"
        # still mean what they meant before this existed.
        if noun == "timer":
            return run(Intent("timer_cancel", {}), sched, now)
        if noun == "alarm":
            return run(Intent("alarm_cancel", {}), sched, now)
        if rec is not None and noun is not None:
            kind = next(iter(rec.get("nouns") or ("thing",)))
            return Result(f"The last thing set here was {_a(kind)}, not {_a(noun)}, so nothing "
                          f"was cancelled.", n)
        # D6 (the live campaign of 2026-10-25): a COMMAND with nothing to take
        # back is answered here, in one line, instead of being handed to the
        # model for a minute of guessing. "never mind" keeps going to the
        # model: it is ordinary words as well as a command, and a chat that
        # answers it with UNDO_NOTHING_SAID would read as a machine that did not
        # listen.
        if f.get("soft"):
            return None
        again = _settings_undone_recently(conversation, now)
        if again is not None:
            return again
        return Result(UNDO_NOTHING_SAID, n)
    minutes = int(S.UNDO_WINDOW // 60)
    if rec["age"] > S.UNDO_WINDOW:
        if f.get("soft"):
            return None
        sched.forget_set(conversation)
        return Result(f"That was more than {minutes} minutes ago, so nothing was cancelled - "
                      f"delete it under Coming up.", n)
    sched.forget_set(conversation)
    views = [sched.job(i) for i in rec["ids"]]
    waiting = any(v and v.get("state") == "waiting" for v in views)
    if not sched.take_back(rec["ids"]):
        return Result(UNDO_NOTHING_LEFT, n)
    what = rec.get("what") or "it"
    if rec.get("intent") == "todo_add":
        return Result(f"Removed {what}.", n, list(rec["ids"]))
    said = f"Cancelled: {what}."
    if waiting:
        said += " Its approval card will set nothing up."
    return Result(said, n, list(rec["ids"]))


def _a(noun: str) -> str:
    return ("an " if noun[:1] in "aeiou" else "a ") + noun


def _run_missed(sched, now: float, seen: Optional[float]) -> Result:
    """"What did I miss?" - the briefing's builder, since the owner last
    talked to Jarvis. Reads only; private, like the briefing."""
    n = "missed"
    try:
        import jarvis_briefing as B
    except Exception:
        return Result(BRIEFING_MISSING, n)
    b = B.build_missed(sched=sched, now=now, since=seen)
    return Result(b["text"], n, private=True, read=list(b.get("read") or []))


def repr_q(text: str) -> str:
    return f"\"{text}\""


def _alarm_words(a: dict, now: float) -> str:
    import jarvis_schedule as S
    if a.get("repeats"):
        return a.get("repeat") or "a repeating alarm"
    if a.get("due") is None:
        return "an alarm"
    return S.when_words(a["due"], now)


def _twelve_note(hour: Optional[int], minute: int) -> str:
    """When the owner said a "12" with no am/pm (or "12 at night"), the time is
    said back as "12:00 midnight" or "12:00 noon", with how to get the other."""
    if hour not in (0, 12):
        return ""
    word, other = ("midnight", "12 noon") if hour == 0 else ("noon", "midnight")
    return f" That is 12:{minute:02d} {word}. If you meant the other, say \"{other}\"."


def _set_at(kind: str, w: When, text: str, sched, now: float, n: str,
            steps: Optional[list] = None) -> Result:
    r = _set_at_plain(kind, w, text, sched, now, n, steps=steps)
    if w.said12 and r.ids:
        if w.rule is not None:
            hh, _, mm = str(w.rule.get("at") or "").partition(":")
            note = _twelve_note(int(hh) if hh.isdigit() else None, int(mm) if mm.isdigit() else 0)
        else:
            lt = time.localtime(w.at)
            note = _twelve_note(lt.tm_hour, lt.tm_min)
        r.reply += note
    return r


def _set_at_plain(kind: str, w: When, text: str, sched, now: float, n: str,
                  steps: Optional[list] = None) -> Result:
    """ONE reminder (or alarm), from chat, with no card.

    `steps` (2026-11-03) makes it a ROUTINE: the same door, the same cards (none),
    and the same "cancel that" window - plus ONE `jarvis_receipts` entry, so
    Undo outlives the 120-second window. Creating is cardless because it always
    was; pressing Undo afterwards raises the ordinary undo card, because undo is
    a mutating action (JARVIS-API section 21.15)."""
    import jarvis_schedule as S
    noun = "Alarm" if kind == "alarm" else "Reminder"
    # `steps` rides along ONLY when this really is a routine (2026-11-04). A
    # plain reminder keeps the exact call it always made, so a Scheduler that
    # predates routines - and a test double written against that signature -
    # still answers a reminder instead of raising TypeError on a keyword it has
    # never heard of. `steps=None` would be the same call for today's
    # jarvis_schedule; not sending it is what keeps the older one working.
    routine = {"steps": steps} if steps else {}
    if w.rule is not None:
        try:
            j = sched.add_repeat(kind, w.rule, text, source="quick", **routine)
        except (ValueError, OverflowError) as exc:
            return Result(S._sentence(exc), n)
        words = S.rule_words(j.get("rule") or w.rule)
        what = f"the repeating {kind} ({words})"
        if j.get("state") == "waiting":
            return Result(f"That repeats ({words}), so there is an "
                          f"approval card for it on your screen. {UNTIL_APPROVED}", n,
                          [j["id"]], made=[j["id"]], what=what, nouns=(kind,))
        # A plain repeat needs no card (2026-09-26): set up now, and the
        # answer says when it next goes off, as the card used to.
        if steps:
            return _routine_result(j, sched, now, n, what, kind)
        return Result(S.repeat_set_words(j, now), n, [j["id"]], made=[j["id"]], what=what,
                      nouns=(kind,))
    if w.passed:
        return Result(f"{S.when_words(w.at, now)} has already passed. Say another time.", n)
    try:
        j = sched.add_at(kind, w.at, text, source="quick", **routine)
    except (ValueError, OverflowError) as exc:
        return Result(S._sentence(exc), n)
    what = f"the {kind} for {S.when_words(w.at, now)}"
    if steps:
        return _routine_result(j, sched, now, n, what, kind)
    if w.at - now < 3600 and kind == "reminder" and not w.default_time:
        return Result(f"{noun} set for {S.clock(w.at)}, in {S.length_words(w.at - now)}.",
                      n, [j["id"]], made=[j["id"]], what=what, nouns=(kind,))
    return Result(f"{noun} set for {S.when_words(w.at, now)}.", n, [j["id"]],
                  made=[j["id"]], what=what, nouns=(kind,))


def _routine_result(j: dict, sched, now: float, n: str, what: str,
                    kind: str) -> Result:
    """The numbered echo of a routine just set up, and its ONE Undo receipt.

    ONE function, so chat and both apps say the same words from the same source
    (`jarvis_schedule._step_words`), and the receipt is written only once the
    row exists - the id is what it needs."""
    import jarvis_schedule as S
    parts = j.get("steps") or []
    anchor = j.get("due")
    if anchor is None:
        anchor = float(now)
    head = f"{j.get('text') or 'Routine'} set for {S.when_words(float(anchor), now)}"
    lines = [f"{head}, in {len(parts)} parts:"]
    lines.extend(S._step_words(parts, float(anchor)))
    lines.append('Say "cancel that" to undo, or edit it under Coming up.')
    said = "\n".join(lines)
    try:
        # ONE receipt per routine created cardlessly, so Undo outlives the
        # 120-second "cancel that" window. A creation has nothing to snapshot
        # BEFORE it, so this is written after the row exists - a stated
        # deviation from `record()`'s "before the change" docstring. If it
        # returns "" nothing is lost: "cancel that" still works for 120 s.
        S.record_routine_receipt(str(j.get("id") or ""), parts, said)
    except Exception:
        pass
    return Result(said, n, [j["id"]], made=[j["id"]], what=what, nouns=(kind,))


BRIEFING_MISSING = ("Your PC's Jarvis does not have the morning briefing yet - run "
                    "apply-patches.ps1 on the PC.")


def _briefing_words(j: dict, now: float) -> str:
    import jarvis_schedule as S
    if j.get("repeats"):
        words = j.get("repeat") or "a repeating briefing"
        if j.get("state") == "waiting":
            words += " (waiting for your yes on the approval card)"
        elif j.get("state") == "paused":
            words += " (paused)"
        return words
    if j.get("due") is None:
        return "a briefing"
    return S.when_words(j["due"], now)


def _run_weather(now: float) -> Optional[Result]:
    """"What's the weather?" from the owner's own Home Assistant - the
    briefing's own read (jarvis_briefing.weather_now), no model. Not
    private (nothing of the owner's is in it), but the forecast is outside
    text, so `read` marks the conversation as having read Home Assistant.
    A PC without the briefing module hands the question to the model."""
    try:
        import jarvis_briefing as B
    except Exception:
        return None
    try:
        got = B.weather_now(now=now)
    except Exception:
        return None
    return Result(str(got.get("text") or ""), "weather_now", read=list(got.get("read") or []))


def _run_news() -> Optional[Result]:
    """"Read me the news" - the owner's own listed feeds
    (jarvis_news.sentence), no model. Headlines are outside text, so `read`
    marks the conversation as having read a news feed."""
    try:
        import jarvis_news as NEWS
    except Exception:
        return None
    try:
        got = NEWS.sentence()
    except Exception:
        return None
    return Result(str(got.get("said") or ""), "news_read", read=list(got.get("read") or []))


NEWS_MISSING = "Your PC's Jarvis cannot show news feeds yet - run apply-patches.ps1 on the PC."


def _run_news_add(url: str) -> Optional[Result]:
    """"Add this feed: <url>" - ONE approval card (jarvis_news.request_add),
    the same shape as "tell me when" setting up a watch. Only the owner's
    own words: a pasted or shared address still raises this same one card,
    since news feeds are never learned from outside text either way."""
    try:
        import jarvis_news as NEWS
    except Exception:
        return Result(NEWS_MISSING, "news_add")
    try:
        code, out = NEWS.request_add({"url": url})
    except Exception as exc:
        return Result(f"Jarvis could not add that feed ({type(exc).__name__}).", "news_add")
    if code == 200:
        return Result(str(out.get("message") or "That feed is already listed."), "news_add")
    if code in (400, 409, 503):
        return Result(str(out.get("error") or "That address could not be added."), "news_add")
    return Result("That needs your yes on the approval card, which shows the address in full. "
                  "Then your morning briefing (and \"read me the news\") can show its "
                  "headlines - never the article text.", "news_add")


def _run_news_remove(url: str) -> Optional[Result]:
    """"Remove that feed: <url>" - at once, no card."""
    try:
        import jarvis_news as NEWS
    except Exception:
        return Result(NEWS_MISSING, "news_remove")
    try:
        _code, out = NEWS.request_remove({"url": url})
    except Exception as exc:
        return Result(f"Jarvis could not remove that feed ({type(exc).__name__}).", "news_remove")
    return Result(str(out.get("message") or ""), "news_remove")


def _run_news_list() -> Optional[Result]:
    try:
        import jarvis_news as NEWS
    except Exception:
        return Result(NEWS_MISSING, "news_list")
    listed = NEWS.feeds()
    if not listed:
        return Result(NEWS.EMPTY, "news_list")
    return Result("\n".join(f"- {u}" for u in listed), "news_list")


def _briefing_without_repeats(text: str) -> str:
    """The briefing's lines with a Pulse line that repeats a section dropped.

    R3 of the live campaign (2026-10-25) printed "Today: Nothing else set for
    today." and then "Pulse: Nothing else set for today." - the Pulse is built
    from the same summaries the sections above already said, so on a quiet day
    the whole Pulse half is those two lines said twice.

    Conservative on purpose, and only about EXACT repeats: a "Pulse: X" line is
    dropped when some earlier line already ends in exactly X ("<Title>: X").
    Nothing is reworded, reordered or summarised, and a Pulse line that adds
    anything at all stays.
    """
    if not text:
        return text
    lines = text.split("\n")
    summaries = set()
    for line in lines:
        head, sep, tail = line.partition(": ")
        if sep and head and not head.startswith(("Pulse", "-", "(", " ")):
            summaries.add(" ".join(tail.split()))
    if not summaries:
        return text
    kept = []
    for line in lines:
        if line.startswith("Pulse: ") and " ".join(line[len("Pulse: "):].split()) in summaries:
            continue
        kept.append(line)
    return "\n".join(kept)


QUOTE_MISSING = ("Your PC's Jarvis does not have the quote feature yet - run "
                 "apply-patches.ps1 on the PC.")


def _run_quote(intent: Intent, sched, now: float) -> Result:
    """A quote (jarvis_quotes.py, 2026-11-05): the words now, or set up a
    repeating one - which is the scheduler's ONE schedule_repeat card, the
    same one a repeating briefing raises. Nothing is written, no model is
    asked, and nothing leaves this PC."""
    n, f = intent.name, intent.f
    try:
        import jarvis_quotes as Q
    except Exception:
        return Result(QUOTE_MISSING, n)
    import jarvis_schedule as S
    if n == "quote_now":
        # `now` is the scheduler's clock, so a test with a hand-moved clock and
        # a real afternoon agree about which day it is.
        return Result(Q.today_line(now), n)
    jobs = Q.setups(sched)
    if n == "quote_list":
        if not jobs:
            return Result("No quote is set up. Say \"send me a quote every morning "
                          "at 8\" to set one up, or \"send me a quote\" for one now.", n)
        words = _join(_quote_words(j, now) for j in jobs[:4])
        return Result(("Your quote: " if len(jobs) == 1 else f"{len(jobs)} quotes: ")
                      + words + ".", n, [j["id"] for j in jobs[:4]])
    if n == "quote_cancel":
        if not jobs:
            return Result("No quote is set up.", n)
        if len(jobs) > 1:
            return Result(f"You have {len(jobs)} quotes set up. Delete the one you mean "
                          "under Coming up.", n)
        code, out = sched.act(jobs[0]["id"], "delete")
        if code != 200:
            return Result(out.get("error") or "That did not work.", n)
        return Result("Stopped your quote.", n, [jobs[0]["id"]])
    # quote_set
    w: When = f["when"]
    if w.rule is not None:
        try:
            j = sched.add_repeat(Q.KIND, w.rule, "", source="quick")
        except (ValueError, OverflowError) as exc:
            return Result(S._sentence(exc), n)
        words = S.rule_words(j.get("rule") or w.rule)
        return Result(f"That quote repeats ({words}), so there is an approval card for it "
                      f"on your screen. {UNTIL_APPROVED}", n, [j["id"]], made=[j["id"]],
                      what=f"the repeating quote ({words})", nouns=("quote",))
    if w.passed:
        return Result(f"{S.when_words(w.at, now)} has already passed. Say another time.", n)
    try:
        j = sched.add_at(Q.KIND, w.at, "", source="quick")
    except (ValueError, OverflowError) as exc:
        return Result(S._sentence(exc), n)
    return Result(f"Quote set for {S.when_words(w.at, now)}.", n, [j["id"]],
                  made=[j["id"]], what=f"the quote for {S.when_words(w.at, now)}",
                  nouns=("quote",))


def _quote_words(j: dict, now: float) -> str:
    import jarvis_schedule as S
    words = S.rule_words(j.get("rule")) if j.get("repeats") else ""
    if not words:
        words = "at " + str(j.get("when") or "")
    if j.get("state") == "waiting":
        return words + " (waiting for your yes on the approval card)"
    return words


def _run_briefing(intent: Intent, sched, now: float) -> Result:
    """The morning briefing: put one together now (reads only - no card), set
    one up (a repeat: the scheduler's ONE card; once: no card), stop ONE, or
    say when."""
    import jarvis_schedule as S
    n, f = intent.name, intent.f
    try:
        import jarvis_briefing as B
    except Exception:
        return Result(BRIEFING_MISSING, n)
    if n == "briefing_now":
        b = B.make(sched=sched, now=now, source="chat")
        # Private: it quotes the calendar, reminders and the to-do list, so a
        # spoken question's answer stays on screen under the apps' rule.
        # `_briefing_without_repeats`: the Pulse half repeats the section lines
        # word for word on a quiet day (D11a, the live campaign of 2026-10-25).
        return Result(_briefing_without_repeats(str(b["text"] or "")), n,
                      private=True, read=list(b.get("read") or []))
    jobs = B.setups(sched)
    if n == "briefing_list":
        if not jobs:
            return Result("No briefing is set up. Say \"brief me every weekday at 7\" to set "
                          "one up, or \"brief me now\".", n)
        words = _join(_briefing_words(j, now) for j in jobs[:4])
        return Result(("Your morning briefing: " if len(jobs) == 1
                       else f"{len(jobs)} briefings: ") + words + ".", n,
                      [j["id"] for j in jobs[:4]])
    if n == "briefing_cancel":
        if not jobs:
            return Result("No briefing is set up.", n)
        if len(jobs) > 1:
            words = _join(_briefing_words(j, now) for j in jobs[:4])
            return Result(f"You have {len(jobs)} briefings set up: {words}. Delete the one you "
                          f"mean under Coming up.", n)
        code, out = sched.act(jobs[0]["id"], "delete")
        if code != 200:
            return Result(out.get("error") or "That did not work.", n)
        return Result(f"Stopped your briefing ({_briefing_words(jobs[0], now)}).", n,
                      [jobs[0]["id"]])
    # briefing_set
    w: When = f["when"]
    if w.rule is not None:
        try:
            j = sched.add_repeat(B.KIND, w.rule, "", source="quick")
        except (ValueError, OverflowError) as exc:
            return Result(S._sentence(exc), n)
        words = S.rule_words(j.get("rule") or w.rule)
        return Result(f"That repeats ({words}), so there is an "
                      f"approval card for it on your screen. {UNTIL_APPROVED}", n, [j["id"]],
                      made=[j["id"]], what=f"the repeating briefing ({words})",
                      nouns=("briefing",))
    if w.passed:
        return Result(f"{S.when_words(w.at, now)} has already passed. Say another time.", n)
    try:
        j = sched.add_at(B.KIND, w.at, "", source="quick")
    except (ValueError, OverflowError) as exc:
        return Result(S._sentence(exc), n)
    return Result(f"Briefing set for {S.when_words(w.at, now)}.", n, [j["id"]],
                  made=[j["id"]], what=f"the briefing for {S.when_words(w.at, now)}",
                  nouns=("briefing",))


def answer(text, *, sched=None, now: Optional[float] = None,
           conversation: Optional[str] = None, seen: Optional[float] = None,
           temporary: bool = False, private: bool = False, peer=None, local=None,
           messages=None, desktop=None,
           client_surface: Optional[str] = None,
           live: bool = False) -> Optional[Result]:
    """Match and act. None: not ours - ask the model. `conversation`: the
    request's conversation_id, so "cancel that" takes back only what was set
    in it; `seen`: when the owner last talked to Jarvis before this turn;
    `temporary`: a temporary chat (2026-09-27's "from now on ..."); `private`:
    a PRIVATE chat (the architect's H10 ruling, 2026-10-25) - strictly
    reads-only. No state-changing answer runs for it: a mutating intent gets
    back the one refusal sentence BEFORE anything is changed or receipted, and
    a read-only intent goes to the model instead, so this path opens no
    scheduler and writes nothing. An ordinary chat is untouched. `peer`/
    `local`: the request's own address, for a setting on jarvis_owner_check.
    PC_ONLY_ACTIONS (jarvis_settings_registry.py, 2026-09-27). `live`: the turn
    was spoken in Jarvis Live (2026-11-03) - passed straight down, read once by
    `_live_body` in `answer_turn`, and used only for a carded setting change's
    one calm line."""
    now = time.time() if now is None else now
    # Chat co-creation of a personality (2026-10-25, jarvis_personality_creator.py):
    # "make me a personality like ..." drafts it with the LOCAL model in the
    # conversation; "save it" stores it through jarvis_manner's own save path.
    # It runs BEFORE the grammar below, so while a draft is pending a plain
    # "save it" cannot be mistaken for anything else. The import is wrapped and
    # a backend without the module keeps exactly the old behaviour.
    try:
        import jarvis_personality_creator as _creator
        _made = _creator.handle(text, conversation=conversation, temporary=temporary)
    except Exception:
        _made = None
    if _made is not None:
        return Result(str(_made.get("reply") or ""),
                      str(_made.get("intent") or "personality_draft"))
    intent = match(text, now, conversation)
    if intent is None:
        # GOOGLE CALENDAR: READS AND EVENT CHANGES, AND ONLY THOSE (2026-10-28).
        # Asked HERE - after the fast path has declined - so one sentence has
        # one owner: "connect my calendar" is the connect-account card's (in
        # `_settings_adjust`), a setup shape the card does not claim is
        # `calendar_setup`'s, and the reads and event changes are this one's.
        # `jarvis_google_calendar.answer()` still carries a connect branch;
        # from here it is UNREACHABLE on purpose, because a connect sentence
        # never gets this far - so it cannot compete for "connect".
        # `not private` because a private chat must not reach Google at all
        # (private-chat.patch: reads-only, nothing outside), and the import is
        # inside the guard so a backend without the module is unchanged.
        if not private:
            try:
                import jarvis_google_calendar as _gcal
                _said = _gcal.answer(text)
            except Exception:               # noqa: BLE001 - module absent
                _said = None
            if _said is not None:
                return Result(str(_said), "google_calendar", read=["calendar_read"])
        return None
    if private and intent.name not in _PRIVATE_DETERMINISTIC_READS:
        # private-chat.patch: the whole fast path is OFF in a private chat,
        # except the deterministic reads the local code can answer itself
        # (_PRIVATE_DETERMINISTIC_READS, ruling Q3 2026-11-07).
        # Refuse, in words, before a single state change or undo receipt -
        # and do not guess at what a read-only intent may write along the way:
        # hand it to the model like any ordinary question instead.
        #
        # The six hard safety sentences are the one exception (2026-11-06): a
        # fixed refusal reads nothing, calls nothing and writes nothing, and
        # "pretend I already approved" is exactly the sentence that must never
        # reach a model that might agree with it.
        if intent.name.startswith("safety_"):
            return Result(_SAFETY_WORDS[intent.name], intent.name, private=True)
        if intent.name in READ_ONLY_INTENTS:
            return None
        return Result(_private_refusal(), intent.name, private=True)
    if sched is None:
        import jarvis_schedule
        sched = jarvis_schedule.get()
    res = run(intent, sched, now, conversation=conversation, seen=seen, temporary=temporary,
             peer=peer, local=local, messages=messages, desktop=desktop,
             client_surface=client_surface, live=live)
    if res is not None:
        try:
            sched.mark_command(text)
        except Exception:
            pass
        if res.intent not in READ_ONLY_INTENTS:
            # Wave 8.2 (2026-11-07): an answer that CHANGED something is
            # exactly the moment the change journal should record it - the
            # snapshot it compares is the program's own current state, so a
            # change made through the apps is caught the next time a change
            # runs here too.
            try:
                _awareness_note()
            except Exception:
                pass
        try:
            if res.made and conversation:
                sched.note_set(conversation, res.made, res.what, res.intent, nouns=res.nouns)
            elif res.intent != "undo" and conversation and res.intent not in READ_ONLY_INTENTS:
                # Something else CHANGED since: "cancel that" would now mean
                # THAT, which cannot be taken back - so nothing can.
                #
                # D6 (the live campaign of 2026-10-25). This used to run for
                # EVERY quick answer that created nothing, including a plain
                # read - so after "remind me next time ..." and then "what
                # will you remind me of next time?", "cancel that" no longer
                # meant the reminder: it fell to the model (69.6 s) and the
                # reminder stayed. A read-only answer changes nothing, so it
                # must not take the record away. `READ_ONLY_INTENTS` is the
                # list of answers that change nothing at all; anything not on
                # it (including an intent added later) keeps the old, safe
                # behaviour.
                sched.forget_set(conversation)
        except Exception:
            pass
    return res

# --------------------------------------------------------------------------
#   Manner: warm or plain (2026-09-25)
# --------------------------------------------------------------------------
#
# The owner's decision: warm and brief by default, with a "Plain" option;
# manner changes only how Jarvis phrases things (jarvis_manner.py). The
# sentences run() makes above ARE the plain wording. Each short one has a
# warm wording here, matched on the whole plain sentence, with every part
# that carries a fact (a length, a time, a name, "no", "already") taken over
# word for word - test_manner.py checks both wordings of each carry the same
# facts. Anything not listed (the to-do list read out, a briefing, a card's
# "That repeats..." line, a repeat's "... set up, every ... Next: ..." line,
# an error) is the same in both.

_WARM = [(re.compile(rx), warm) for rx, warm in (
    (r"No timer is running\.", "There's no timer running right now."),
    (r"(?P<left>[^;:().,]+) left \(paused\)\.", "{left} to go - it's paused."),
    (r"(?P<left>[^;:().,]+) left\.", "{left} to go."),
    (r"(?P<name>.+ timer) cancelled\.", "Okay, {name_l} cancelled."),
    (r"Paused, with (?P<left>.+) left\.", "Paused - {left} to go."),
    (r"Resumed\.", "Okay, it's running again."),
    (r"(?P<verb>Added|Took off) (?P<len>[^.]+)\. (?P<rest>.+)", "Okay - {verb_l} {len}. {rest}"),
    (r"No alarm is set\.", "You don't have any alarms set."),
    (r"There is no alarm like that set\.", "I can't find an alarm like that."),
    (r"Alarm for (?P<when>.+) cancelled\.", "Okay, your alarm for {when} is cancelled."),
    (r"One alarm: (?P<when>.+)\.", "You have one alarm: {when}."),
    (r"That is already on your to-do list\.", "That's already on your to-do list."),
    (r"Added to your to-do list\.", "Got it - it's on your to-do list."),
    (r"Your to-do list is empty\.", "Nothing on your to-do list right now."),
    (r"Marked done\.", "Okay, marked done."),
    (r"Removed from your to-do list\.", "Okay, removed from your to-do list."),
    (r"(?P<when>[^.]+) has already passed\. Say another time\.",
     "{when} has already passed - what other time would you like?"),
    (r"No briefing is set up\.", "You don't have a briefing set up."),
    (r"Stopped your briefing \((?P<when>.+)\)\.", "Okay, I've stopped your briefing ({when})."),
    (r"(?P<what>Timer|[^.]+ timer|Alarm|Reminder|Briefing) set for (?P<when>[^;]+)\.",
     "Got it - {what_l} set for {when}."),
)]


def _lower_first(text: str) -> str:
    return text[:1].lower() + text[1:] if text else text


def in_manner(reply: str, manner: Optional[str] = None) -> str:
    """`reply` in the owner's manner: the warm wording when there is one and
    the manner is warm, else `reply` as it is. `manner` None reads the
    setting (jarvis_manner.py); a backend without it keeps the plain words."""
    if manner is None:
        try:
            import jarvis_manner
            manner = jarvis_manner.current()
        except Exception:
            return reply
    if manner != "warm" or not isinstance(reply, str):
        return reply
    for rx, warm in _WARM:
        m = rx.fullmatch(reply)
        if m:
            g = m.groupdict()
            g.update({f"{k}_l": _lower_first(v) for k, v in list(g.items())})
            return warm.format(**g)
    return reply

# --------------------------------------------------------------------------
#   /api/chat
# --------------------------------------------------------------------------

_OWN_WORDS = ("typed", "voice")


def newest_own_words(body) -> Optional[str]:
    """The newest message's words when they are the owner's own and nothing
    else came with them; None otherwise (then the model answers, as before).

    Read off the request AS IT ARRIVED - the provenance tags come off before
    any model sees the messages (chat-history.patch)."""
    if not isinstance(body, dict):
        return None
    msgs = body.get("messages")
    if not isinstance(msgs, list) or not msgs:
        return None
    msgs = [m for m in msgs if isinstance(m, dict)]
    if not msgs:
        return None
    if any(m.get("role") == "system" for m in msgs):
        return None         # the app sent text of its own (audit M1)
    last = msgs[-1]
    if last.get("role") != "user" or last.get("provenance") not in _OWN_WORDS:
        return None
    if len(msgs) > 1 and msgs[-2].get("role") == "user" \
            and msgs[-2].get("provenance") in ("shared", "clipboard"):
        return None         # sent with a share or the clipboard
    content = last.get("content")
    if isinstance(content, list):
        if any(isinstance(p, dict) and p.get("type") not in (None, "text") for p in content):
            return None     # a picture: the model's job
        content = " ".join(str(p.get("text") or "") for p in content if isinstance(p, dict))
    if not isinstance(content, str) or not content.strip():
        return None
    return content


_CONVERSATION = re.compile(r"[A-Za-z0-9_-]{8,64}")


def conversation_of(body) -> Optional[str]:
    """The request's conversation_id (JARVIS-API 18.1), or None when there
    is none or it is not one - then "cancel that" has nothing to take back."""
    cid = body.get("conversation_id") if isinstance(body, dict) else None
    return cid if isinstance(cid, str) and _CONVERSATION.fullmatch(cid) else None


def _touch(now: Optional[float]) -> Optional[float]:
    """Note that the owner talked to Jarvis now (for "what did I miss?");
    the time before this one, or None. Never raises."""
    try:
        import jarvis_briefing as B
        return B.touch(now)
    except Exception:
        return None


def answer_turn(body, *, sched=None, now: Optional[float] = None,
                peer=None, local=None, private: Optional[bool] = None,
                client_surface: Optional[str] = None) -> Optional[Result]:
    """For /api/chat: the fast path's answer to this turn, or None. Every
    chat request counts as the owner being here ("what did I miss?" asks
    since the one before), whoever's words it carries. `peer`/`local`: the
    request's own address (schedule.patch's do_POST reads it the same way
    owner-check.patch's own wrapper does) - passed all the way down so a
    setting on jarvis_owner_check.PC_ONLY_ACTIONS can tell this PC's own
    chat from the phone's, exactly as its REST route already does
    (jarvis_settings_registry.py, 2026-09-27). This function never invents
    either value: it hands whatever it was given straight to
    jarvis_owner_check.from_this_pc, unchanged - the SAME function, and the
    SAME "cannot be placed counts as this PC" rule, every other caller of
    that function already lives with. schedule.patch always supplies the
    real address; a caller that omits it (an older test, a script) gets
    that function's own default, not a stricter or looser one made up
    here."""
    # 2026-10-28, the AI-safety audit's finding M1: a crisis turn is NEVER
    # answered by the fast path, and it is decided HERE rather than in one
    # caller. jarvis_hud.py used to run this function BEFORE it asked whether
    # the message was a crisis, so a distress sentence that also fitted this
    # grammar was answered here and the route returned - no 988/911 line, no
    # calm panel, because the header had already gone. Every caller of the
    # fast path inherits this refusal now, including Live and the phone's own
    # chat, and the check is jarvis_wellbeing.crisis_in_turn: the newest user
    # message, whatever its provenance - the same rule the answering turn and
    # the HUD's route header use, so the three cannot disagree.
    #
    # Returning None is what "the fast path has no answer for this turn"
    # already means everywhere (answer_turn's own docstring), so the turn
    # falls through to the local model, which offers no tools on a crisis turn
    # and appends the help text. Nothing is written, touched or counted here.
    try:
        import jarvis_wellbeing
        if jarvis_wellbeing.crisis_in_turn(
                body.get("messages") if isinstance(body, dict) else None):
            return None
    except Exception:
        pass
    # private-chat.patch: a private turn must not even write the "owner was
    # here" touch (jarvis_briefing) or drop this conversation's undo record,
    # so both are skipped below. `private` is derived from the body when the
    # caller did not say (an older hud ignores the flag; enforcing it here
    # anyway is the fail-safe direction), and only JSON `true` counts.
    private = _private_body(body) if private is None else bool(private)
    seen = None if private else (
        _touch(now) if isinstance(body, dict) and body.get("messages") else None)
    conversation = conversation_of(body)
    # "temporary": true (temporary-chat.patch) - the same one-line check
    # jarvis_hud.py's own _temporary_chat(body) makes; needed here for
    # "from now on ..." (2026-09-27), which keeps a temporary chat's style
    # change in that chat only, never written to manner.json.
    temporary = _temporary_body(body)
    text = newest_own_words(body)
    # `desktop`: the app's own report of the build that sent this chat, built
    # in Rust (commands.rs `chat_extras`) and never by a page. The update
    # answers need it, and nothing else reads it (2026-10-26).
    desktop = body.get("desktop") if isinstance(body, dict) else None
    # `live` (2026-11-03): read ONCE, here, with the same rule jarvis_agent's
    # own `_TurnWatch` makes - `provenance: "voice"` AND `live: true` on the
    # newest user message. It is never inferred from the text and never from
    # the app's say-so alone, so a typed chat cannot become a Live turn.
    live = _live_body(body)
    res = None if text is None else answer(text, sched=sched, now=now,
                                           conversation=conversation, seen=seen,
                                           temporary=temporary, private=private,
                                           peer=peer, local=local,
                                           messages=body.get("messages"),
                                           desktop=desktop,
                                           client_surface=client_surface,
                                           live=live)
    if res is None and conversation and not private:
        # The model answers this turn: "cancel that" after it is about the
        # model's answer, never about a reminder set before it.
        _forget_set(sched, conversation)
    if res is not None:
        # Live is spoken, so a long quoted note says its start and where it
        # stopped (2026-11-05). Typed answers are untouched: the full capped
        # text and the "N more characters" tail stay exactly as they were.
        if live:
            res.reply = _live_said(res.reply, res.intent)
        # Wording only (jarvis_manner.py): the same facts, the owner's
        # manner - this conversation's own "from now on ..." override when
        # it is a temporary chat that has one, else the PC's saved setting.
        manner = None
        try:
            import jarvis_manner
            manner = jarvis_manner.current(conversation if temporary else None)
        except Exception:
            pass
        res.reply = in_manner(res.reply, manner)
    return res


#: private-chat.patch: the refusal sentence's fallback, byte-identical to the
#: shipped module's REFUSAL (backend/test_private_chat.py asserts the equality,
#: so they cannot drift). The gate itself is one strict inline test, so a
#: backend WITHOUT jarvis_private_chat.py still refuses - a private request
#: must never become an ordinary one because a file is missing.
_PRIVATE_REFUSAL_FALLBACK = (
    "A private chat can read, search, and answer, but it doesn't change "
    "settings, save items, or run actions — switch back to a normal chat "
    "to do that.")


def _private_refusal() -> str:
    """The one refusal sentence: the shipped module's copy, or its
    byte-identical fallback when that module is missing or broken."""
    try:
        import jarvis_private_chat
        return jarvis_private_chat.REFUSAL
    except Exception:
        return _PRIVATE_REFUSAL_FALLBACK


def _private_body(body) -> bool:
    """private-chat.patch: is this request a private chat? FAIL CLOSED: the
    canonical reading is jarvis_private_chat.is_private (JSON `true`, and
    nothing else), and when that module cannot be imported the same one-line
    test is made here rather than answering False. A missing or broken gate
    must refuse the private turn, never turn it into an ordinary one."""
    try:
        import jarvis_private_chat
        return bool(jarvis_private_chat.is_private(body))
    except Exception:
        return isinstance(body, dict) and body.get("private") is True


def _temporary_body(body) -> bool:
    """Is this request a temporary chat? `temporary: true`, or a game or
    role-play the PC has seen in this conversation - the same test the chat
    route makes (jarvis_hud._temporary_chat, games-temporary.patch). This
    path used to read the flag alone, so in a role-play chat "where is my
    passport" was answered from saved memory and "from now on, be plainer"
    was written to manner.json for good (the second chat audit,
    2026-09-28, finding 7, reproduced). Without jarvis_intake: the flag."""
    if _private_body(body):
        # private-chat.patch: a private chat IS a temporary chat for memory,
        # history and learning - plus it refuses every write and every action
        # (the refusal gate in answer() above). Same meaning as
        # jarvis_hud._temporary_chat's own private branch.
        return True
    try:
        import jarvis_intake
        return bool(jarvis_intake.temporary_body(body))
    except Exception:
        return isinstance(body, dict) and body.get("temporary") is True


#: How much of a note a SPOKEN answer reads before it says where it stopped.
#: Live is heard, not scrolled: a 4,000-character note is a minute of speech
#: the owner did not ask for, and the typed answer keeps the whole capped text.
LIVE_NOTE_CHARS = 1000
LIVE_NOTE_START = "...(that is the start)"


def _live_said(reply: str, intent: str) -> str:
    """A long note read shortened for speech, and it SAYS where it stopped.

    Only `note_read` - every other quick answer is already short enough, and
    this must never quietly cut an answer that is not a quoted file. A short
    note is returned exactly as typed.
    """
    if intent != "note_read":
        return reply
    text = str(reply or "")
    if len(text) <= LIVE_NOTE_CHARS:
        return text
    return text[:LIVE_NOTE_CHARS].rstrip() + " " + LIVE_NOTE_START


def _live_body(body) -> bool:
    """Is this request a JARVIS LIVE turn (2026-11-03)?

    The same reading jarvis_agent's own `_TurnWatch` makes (and the same one
    test_live_parity.py pins for the marks both apps send): the NEWEST user
    message carries `provenance: "voice"` AND `live: true`. A `live` mark on a
    typed message is not a Live turn, and a spoken message without the mark is
    not one either. Anything unreadable counts as NOT Live, so a broken request
    can never make the spoken-shortening path fire in a typed chat.
    """
    if not isinstance(body, dict):
        return False
    msgs = body.get("messages")
    if not isinstance(msgs, list):
        return False
    users = [m for m in msgs if isinstance(m, dict) and m.get("role") == "user"]
    if not users:
        return False
    last = users[-1]
    return last.get("provenance") == "voice" and last.get("live") is True


def _forget_set(sched, conversation) -> None:
    try:
        if sched is None:
            import jarvis_schedule
            sched = jarvis_schedule._SCHED
        if sched is not None:
            sched.forget_set(conversation)
    except Exception:
        pass


def route_fields(res: Result) -> dict:
    """What an answer made here puts in X-Jarvis-Route. It used no memory and
    no model; a reply that reads the owner's list out is `gate: "private"`,
    like notes, so a voice answer stays on screen under the apps' private
    rule."""
    out = {"quick": res.intent, "where": "local", "lane": LANE,
           "inject_memory": False, "injected_facts": 0, "injected_ids": [],
           "injected_sensitive": 0}
    if res.private:
        out["gate"] = "private"
    if res.facts:
        # "Where did I put ...?" (2026-09-28): the answer quotes saved facts,
        # so it says so exactly as a model answer that used memory does -
        # the same "mem:<id>" ids, and how many are sensitive (both apps
        # keep such an answer on screen unless the owner allowed it).
        out["inject_memory"] = True
        out["injected_facts"] = len(res.facts)
        out["injected_ids"] = [f"mem:{int(i)}" for i in res.facts]
        out["injected_sensitive"] = max(0, min(int(res.facts_sensitive), len(res.facts)))
    if res.open_settings:
        # "open <a settings section>" (jarvis_settings_registry.py,
        # 2026-09-27): the section id both apps' Settings screens already
        # use, so either one can jump straight there. Additive only - every
        # existing reader of X-Jarvis-Route that does not look for this key
        # is unaffected, exactly like `gate` above.
        out["open_settings"] = res.open_settings
    if res.open_app or res.open_app_kind == "jarvis":
        # "open Notion", "open settings", "open Jarvis settings"
        # (jarvis_open.py, the owner's request of 2026-10-10): what to open
        # and which kind it is. An app that reads this opens it itself (the
        # desktop, in Rust, through the Windows shell); an app that does not
        # - the phone - shows the answer and opens nothing, and the answer
        # says "on this PC" so that is not a claim it cannot keep. Additive,
        # like open_settings above.
        #
        # `jarvis` carries `open_place` instead of `open_app`: it is the
        # Settings section id, and "" means the top of the window - a real
        # answer that an empty `open_app` could not carry.
        if res.open_app:
            out["open_app"] = res.open_app
        if res.open_app_kind:
            out["open_app_kind"] = res.open_app_kind
        # A boolean, like `inject_memory` above: True when the backend named
        # the program itself (Windows' own accessories), so the app opens it
        # straight away instead of looking it up on this PC's Start menu.
        out["open_app_built"] = bool(res.open_app_built)
        if res.open_app_kind == "jarvis":
            out["open_place"] = res.open_place or ""
        if res.open_app_note:
            out["open_app_note"] = res.open_app_note
    if res.menu_visibility:
        # "Hide the finance menu" (jarvis_menus.py, 2026-09-30): per device, so each
        # app that hears this applies it to its own menu list. Additive, like
        # open_settings; only present when there is something to apply.
        out["menu_visibility"] = dict(res.menu_visibility)
    if res.face_tuning:
        # Sharpness or frame rate (jarvis_animal.DEVICE_CHANGES, 2026-09-28):
        # per device, so the app that asked applies it to itself - the same
        # additive road as open_settings above.
        out["face_tuning"] = res.face_tuning
    if res.open_brain:
        # "Forget a time frame" (jarvis_forget_range.py, 2026-09-28): the
        # Brain place both apps open, with the list already filled in.
        # "open the second brain" / "open history" / "open tutorials" /
        # "open my notes" (2026-10-31) use the same field for the window and
        # its own places - the apps already open those through open_fix_place.
        # Additive, like open_settings.
        out["open_brain"] = res.open_brain
    if res.topic_id is not None:
        # Topic controls (2026-09-30): the picker opens on this topic; nothing
        # has changed yet. Additive, like file_under.
        out["topic_id"] = int(res.topic_id)
    if res.file_under is not None:
        # Chat tags (2026-09-30): "file under <tag id>" with the search words.
        # The apps show the matches and the banner; nothing is filed until
        # the owner taps a chat.
        out["file_under"] = int(res.file_under)
        out["history_q"] = str(res.history_q or "")
    if res.note_job:
        # "make a note: ..." while its approval card is still up (2026-11-02):
        # the capture job's id, which `GET /api/notes/capture?id=` answers.
        # The app follows it and settles its own "Waiting for your approval."
        # line with the PC's own last sentence ("Filed in Obsidian, <file>.",
        # "You said no, so nothing was written."). Additive, like every key
        # above: an app that does not know it shows the waiting line exactly
        # as it always did. Never the note's text - an id and nothing else.
        out["note_job"] = res.note_job
    if res.call_record:
        # "record call" / "stop recording" (2026-11-04, jarvis_call_notes.py):
        # the machine directive the Android app acts on - {"action": "arm"} or
        # {"action": "stop"}. Additive, like every key above: an app that does
        # not know it shows the words and records nothing. The phone records,
        # the PC transcribes, labels who spoke and writes the note; a feature
        # that is off never reaches here (the answer says so instead).
        out["call_record"] = dict(res.call_record)
    return out


def reply_bytes(reply: str, stream: bool) -> bytes:
    """The whole answer, in the same format a model's answer is sent in
    (jarvis_agent's): Ollama's SSE chunks, or one chat.completion body."""
    cid = f"chatcmpl-jarvis-quick-{int(time.time() * 1000)}"
    created = int(time.time())

    def chunk(delta: dict, finish=None) -> dict:
        return {"id": cid, "object": "chat.completion.chunk", "created": created,
                "model": LANE, "system_fingerprint": "fp_jarvis_quick",
                "choices": [{"index": 0, "delta": delta, "finish_reason": finish}]}

    if stream:
        out = b""
        for obj in (chunk({"role": "assistant", "content": reply}), chunk({}, "stop")):
            out += b"data: " + json.dumps(obj, ensure_ascii=False,
                                          separators=(",", ":")).encode("utf-8") + b"\n\n"
        return out + b"data: [DONE]\n\n"
    return json.dumps({
        "id": cid, "object": "chat.completion", "created": created, "model": LANE,
        "system_fingerprint": "fp_jarvis_quick",
        "choices": [{"index": 0, "message": {"role": "assistant", "content": reply},
                     "finish_reason": "stop"}],
    }, ensure_ascii=False, separators=(",", ":")).encode("utf-8") + b"\n"


def content_type(stream: bool) -> str:
    return "text/event-stream" if stream else "application/json"


# ==========================================================================
#   Full self-awareness: the preset it is on, the benchmarks recorded, the
#   change journal, inventories, per-tool switch states and the same-area
#   groups (Wave 8.2, 2026-11-07; the owner: "full awareness of everything
#   that the jarvis program has, including if anything changes").
#
#   Every word below comes from the program's own registries and stores:
#   jarvis_presets, jarvis_model_knowledge, jarvis_bench, jarvis_settings_
#   registry, jarvis_feature_catalogue. Reads only - no model, no card, no
#   write. The one action (start a benchmark) goes through jarvis_bench's own
#   async runner and its own machine-checkable `confirm` block; it changes no
#   setting, so it raises no card.
# ==========================================================================

_AW_PRESET_CURRENT = re.compile(
    r"(?:what|which)\s+preset\s+(?:am\s+i|are\s+you|are\s+we)\s+"
    r"(?:on|using|running)(?:\s+right\s+now)?"
    r"|(?:what|which)\s+preset\s+is\s+(?:chosen|active|selected|current)"
    r"|(?:what|which)\s+preset\s+(?:am\s+i|are\s+you)\s*", re.I)

_AW_BENCH_HISTORY = re.compile(
    r"(?:what|which)\s+benchmarks?\s+(?:have|has|were|did)\s+(?:been\s+)?"
    r"(?:run|measured|done|recorded|completed)(?:\s+(?:on|for)\s+(?:you|me|this\s+pc))?"
    r"|(?:what|which)\s+(?:are\s+)?(?:your|the)\s+benchmark\s+"
    r"(?:results|numbers|measurements|scores|history)"
    r"|(?:show|tell)\s+me\s+(?:your|the)\s+benchmarks?"
    r"|what\s+have\s+you\s+measured"
    r"|benchmark\s+history", re.I)

_AW_BENCH_RUN = re.compile(
    r"(?:run|do|start|take|perform)\s+(?:a|one|the|another)\s+"
    r"(?:quick\s+|short\s+)?(?:benchmark|speed\s+test|tok/s\s+test|"
    r"tokens?\s+per\s+second\s+test)"
    r"(?:\s+(?:of|on|for)\s+(?:the\s+|your\s+)?(?:current\s+|running\s+)?model)?"
    r"|benchmark\s+(?:yourself|the\s+current\s+model|your\s+current\s+model|"
    r"the\s+running\s+model|this\s+model)"
    r"|(?:run|take)\s+a\s+(?:speed|tok/s)\s+test", re.I)

_AW_BENCH_SUITES = re.compile(
    r"(?:run|start|do|take)\s+(?:the\s+|a\s+|all\s+(?:of\s+)?the\s+)?"
    r"(?:full\s+|complete\s+|quality\s+)?benchmark\s+(?:suites?|set)"
    r"|(?:run|start)\s+(?:the\s+|a\s+)?(?:full|complete|quality)\s+benchmark"
    r"|benchmark\s+(?:your\s+)?(?:quality|quality\s+and\s+speed|speed\s+and\s+quality)"
    r"|measure\s+(?:your\s+)?(?:quality|quality\s+and\s+speed|coding\s+and\s+general)"
    r"|(?:run|start)\s+all\s+(?:the\s+)?benchmark\s+suites?", re.I)

_AW_BENCH_PROGRESS = re.compile(
    r"how(?:'s|\s+is)\s+the\s+benchmark\s+(?:going|doing|coming\s+along)"
    r"|benchmark\s+(?:status|progress|state)"
    r"|is\s+the\s+benchmark\s+(?:done|finished)\s*", re.I)

_AW_BENCH_STOP = re.compile(
    r"(?:stop|cancel|abort)\s+(?:the\s+)?(?:benchmark|bench\s+run)", re.I)

#: "What changed about you?" is the JOURNAL's. A question about the shipped
#: update ("what changed in your last update?") stays `recent_changes`' - it
#: is a different question about a different record, and jarvis_recent_changes
#: has owned it since Wave 8. So this pattern names the journal's shapes only.
_AW_CHANGES = re.compile(
    r"what\s+changed\s+about\s+(?:you|jarvis)"
    r"(?:\s+(?:since|in)\s+(?P<when>yesterday|this\s+morning|today|"
    r"the\s+last\s+\w+|your\s+last\s+update|my\s+last\s+(?:question|visit)))?"
    r"|what\s+changed\s+(?:since\s+(?P<when2>yesterday|this\s+morning|today|"
    r"the\s+last\s+\w+)|recently)"
    r"|what\s+changed\s*"
    r"|(?:any|what)\s+changes?\s+(?:about\s+you|since\s+\w+)"
    r"|what(?:'s|\s+is)\s+new\s+with\s+you", re.I)

_AW_CHANGEABLE = re.compile(
    r"what\s+can\s+(?:you|i)\s+change(?:\s+by\s+(?:chat|asking|voice))?"
    r"|what(?:'s|\s+is)\s+changeable"
    r"|what\s+settings?\s+and\s+tools?\s+can\s+you\s+change", re.I)

_AW_INVENTORY = re.compile(
    r"what\s+do\s+you\s+have(?:\s+in\s+total)?"
    r"|what\s+does\s+(?:the\s+)?(?:program|jarvis)\s+have"
    r"|list\s+everything\s+you\s+have", re.I)

_AW_TOOL_LIST = re.compile(
    r"(?:which|what)\s+tools?\s+(?:are|is)\s+(?:on|off|enabled|disabled|"
    r"turned\s+on|turned\s+off)"
    r"|(?:list|show)\s+(?:me\s+)?(?:the\s+)?tools?\s+(?:that\s+are\s+)?"
    r"(?:on|off|enabled|disabled)"
    r"|(?:which|what)\s+tools?\s+can\s+the\s+(?:ai\s+)?model\s+use", re.I)

_AW_TOOL_STATE = re.compile(
    r"is\s+(?P<name>.+?)\s+(?:on|off|enabled|disabled)\s*"
    r"|can\s+the\s+(?:ai\s+)?model\s+use\s+(?P<name2>.+?)\s*", re.I)

_AW_DESKTOP_ROW = re.compile(
    r"what\s+does\s+(?:the\s+)?(?P<name>.+?)\s+setting\s+do"
    r"|how\s+do\s+i\s+change\s+(?:the\s+)?(?P<name2>.+?)(?:\s+setting)?\s*"
    r"|what\s+is\s+(?:the\s+)?(?P<name3>.+?)\s+setting\s+set\s+to", re.I)

#: Only the VALUE question. "explain the <feature/setting>" is the older
#: `setting_explain` / feature-explain grammar's, and it must keep owning it.
_AW_SETTING_READ = re.compile(
    r"what\s+is\s+(?:the\s+)?(?P<name>.+?)\s+set\s+to\s*", re.I)

#: "Which folders may you look in?" - the read of jarvis_documents.folders().
_AW_FOLDER_LIST = re.compile(
    r"(?:(?:can|could|would)\s+you\s+|please\s+)?"
    r"(?:which|what)\s+folders?\s+(?:may|can|do)\s+(?:you|jarvis)\s+"
    r"(?:look\s+in|see|access|read)"
    r"|(?:which|what)\s+folders?\s+are\s+(?:on\s+)?(?:the\s+)?(?:list|allowed)"
    r"|list\s+(?:your|the)\s+folders?"
    r"|what\s+folders\s+(?:have\s+you\s+got|do\s+you\s+have)", re.I)

#: "Add my downloads folder to the folders Jarvis may look in" / "let Jarvis
#: look in my downloads folder". The PATH is read from the raw sentence (the
#: matching form is lowercased), and resolved by `_folder_path_from_words`.
_AW_FOLDER_ADD = re.compile(
    r"(?:(?:can|could|would)\s+you\s+|please\s+)?"
    r"(?:add|allow)\s+(?P<p1>.+?)\s+to\s+(?:the\s+)?folders?\s+"
    r"(?:jarvis\s+)?(?:may|can)\s+look\s+in"
    r"|let\s+(?:jarvis\s+)?look\s+in\s+(?P<p2>.+?)"
    r"|add\s+(?P<p3>.+?)\s+to\s+(?:your|the)\s+folders?\s+list", re.I)

#: The Windows folders the owner means by their everyday names.
_FOLDER_NAMES = {
    "downloads": "~/Downloads", "download": "~/Downloads",
    "documents": "~/Documents", "document": "~/Documents", "docs": "~/Documents",
    "desktop": "~/Desktop", "pictures": "~/Pictures", "photos": "~/Pictures",
    "music": "~/Music", "videos": "~/Videos", "video": "~/Videos",
    "home": "~",
}


def _folder_path_from_words(words: str) -> str:
    """The path the owner meant, or "" when it cannot be resolved safely."""
    raw = " ".join(str(words or "").strip().strip('"').strip("'").split())
    raw = re.sub(r"^(?:the|my|your)\s+", "", raw, flags=re.I)
    raw = re.sub(r"\s+folder$", "", raw, flags=re.I).strip()
    if not raw:
        return ""
    lowered = raw.lower()
    if lowered in _FOLDER_NAMES:
        return os.path.expanduser(_FOLDER_NAMES[lowered])
    # An explicit path is taken as written when it looks like one; anything
    # else is asked about rather than guessed.
    if re.match(r"^[A-Za-z]:[\\/]", raw) or raw.startswith("~/") or raw.startswith("\\\\"):
        return os.path.expanduser(raw)
    return ""


_AW_AREA = re.compile(
    r"what\s+else\s+(?:affects|touches|is\s+in)\s+(?:the\s+)?(?P<area>.+?)"
    r"(?:\s+area)?\s*"
    r"|what\s+(?:switches|settings|parts?)\s+(?:are\s+)?in\s+(?:the\s+)?"
    r"(?P<area2>.+?)(?:\s+area)?\s*"
    r"|what\s+happens\s+if\s+i\s+change\s+(?P<a>.+?)\s+and\s+(?P<b>.+?)"
    r"\s+together\s*", re.I)


def _awareness_dir() -> str:
    home = (os.environ.get("OPENJARVIS_HOME") or os.environ.get("JARVIS_HOME")
            or os.environ.get("OPENJARVIS_CONFIG_DIR")
            or os.path.expanduser("~/.openjarvis"))
    return os.path.join(home, "self-awareness")


def _safe_todo_carryover_words() -> Optional[str]:
    """The to-do carryover choice, read WITHOUT creating or ticking a scheduler."""
    try:
        import sqlite3
        from pathlib import Path
        import jarvis_schedule as JS
        path = Path(JS.db_path())
        if not path.exists():
            return None
        conn = sqlite3.connect("file:" + str(path).replace("\\", "/") + "?mode=ro",
                               uri=True)
        try:
            row = conn.execute(
                "SELECT value FROM meta WHERE key = 'todo_mode'").fetchone()
        finally:
            conn.close()
        mode = str(row[0]) if row else ""
        if not mode:
            return None
        label = next((str(item.get("label") or "")
                      for item in getattr(JS, "TODO_MODE_WORDS", ())
                      if item.get("value") == mode), "")
        return label or mode
    except Exception:
        return None


def _awareness_snapshot() -> dict:
    """Every awareness-relevant value the local code can read, one flat dict."""
    snap = {}
    try:
        version = _read_version_source()
        if version.get("version"):
            snap["version"] = str(version["version"])
    except Exception:
        pass
    try:
        import jarvis_presets as P
        pid = str(P.choice() or "")
        if pid:
            snap["preset"] = pid
            row = _preset_row(pid) or {}
            if row.get("model"):
                snap["preset_model"] = str(row["model"])
    except Exception:
        pass
    try:
        model = _model_record()
        if model:
            snap["model"] = model
    except Exception:
        pass
    try:
        import jarvis_settings_registry as R
        for setting in (list(R.BOOL_SETTINGS) + list(R.CHOICE_SETTINGS)
                        + list(R.NUMBER_SETTINGS)):
            if setting.key == "todo_carryover":
                # NOT R.current_value here: that reader calls
                # jarvis_schedule.get(), which CREATES/ticks the global
                # scheduler as a side effect - inside an answer, and inside a
                # test that has its own fake scheduler, that fires jobs nobody
                # asked to fire (caught by test_watch_repos on 2026-11-07).
                # The journal reads the same meta value from the same file
                # with sqlite's read-only open instead.
                value = _safe_todo_carryover_words()
            else:
                try:
                    value = R.current_value(setting)
                except Exception:
                    value = None
            if value is not None:
                snap["setting:" + setting.key] = str(value)
        for tool in R.tool_targets():
            try:
                value = R.reading_tool_now(tool)
            except Exception:
                value = None
            if value is not None:
                snap["tool:" + tool] = "on" if value else "off"
        import jarvis_feature_catalogue as C
        snap["count:features"] = len(C.FEATURES)
        snap["count:tools"] = len(R.tool_targets())
        snap["count:settings"] = (len(R.BOOL_SETTINGS) + len(R.CHOICE_SETTINGS)
                                  + len(R.NUMBER_SETTINGS))
    except Exception:
        pass
    try:
        import jarvis_bench as B
        snap["count:bench_runs"] = len(B.BenchLog().runs(limit=500))
    except Exception:
        pass
    return snap


def _awareness_note() -> dict:
    """Diff the snapshot against the last one and journal what changed."""
    snap = _awareness_snapshot()
    folder = _awareness_dir()
    try:
        os.makedirs(folder, exist_ok=True)
    except Exception:
        return snap
    path = os.path.join(folder, "snapshot.json")
    prev = None
    try:
        with open(path, encoding="utf-8") as fh:
            prev = json.load(fh)
    except Exception:
        prev = None
    if isinstance(prev, dict) and prev != snap:
        changed = [{"key": key, "from": prev.get(key), "to": snap.get(key)}
                   for key in sorted(set(prev) | set(snap))
                   if prev.get(key) != snap.get(key)]
        if changed:
            jpath = os.path.join(folder, "changes.jsonl")
            lines = []
            try:
                with open(jpath, encoding="utf-8") as fh:
                    lines = fh.read().splitlines()[-499:]
            except Exception:
                lines = []
            lines.append(json.dumps({"at": int(time.time()), "changed": changed}))
            try:
                with open(jpath, "w", encoding="utf-8") as fh:
                    fh.write("\n".join(lines) + "\n")
            except Exception:
                pass
    try:
        tmp = path + ".tmp"
        with open(tmp, "w", encoding="utf-8") as fh:
            json.dump(snap, fh, indent=1, sort_keys=True)
        os.replace(tmp, path)
    except Exception:
        pass
    return snap


def _awareness_journal_rows() -> list:
    try:
        with open(os.path.join(_awareness_dir(), "changes.jsonl"),
                  encoding="utf-8") as fh:
            return [json.loads(line) for line in fh.read().splitlines() if line.strip()]
    except Exception:
        return []


def _awareness_area_words(area: str) -> str:
    area = area.strip().lower()
    import jarvis_settings_registry as R
    keys = []
    for setting in R.BOOL_SETTINGS:
        if str(setting.section or "").lower() == area:
            keys.append(setting)
    for setting in R.CHOICE_SETTINGS:
        if str(getattr(setting, "where", "") or "").lower() == area:
            keys.append(setting)
    if not keys:
        return ""
    bits = []
    for setting in keys:
        try:
            value = R.current_value(setting)
        except Exception:
            value = None
        bits.append(str(setting.names[0]) + " (" + (value or "value unreadable") + ")")
    return ("The " + area.replace("-", " ") + " area has " + str(len(bits))
            + " parts: " + "; ".join(bits) + ". They act on the same thing, so they "
            "are worth changing one at a time: each change asks its own card where it "
            "needs one, and I record it in the change journal.")


def _run_area_overview(f: dict) -> Result:
    import jarvis_settings_registry as R
    area = str(f.get("area") or "").strip()
    a, b = str(f.get("a") or "").strip(), str(f.get("b") or "").strip()
    if a and b:
        def find(words):
            words = words.strip()
            for finder in (R.find_bool_setting, R.find_choice_setting,
                           R.find_number_setting, R.find_bool_setting_words,
                           R.find_choice_setting_words, R.find_number_setting_words):
                try:
                    got = finder(words)
                except Exception:
                    got = None
                if got is not None:
                    return got
            return None
        sa, sb = find(a), find(b)
        if sa is None or sb is None:
            def fuzzy(words):
                words = words.strip().lower()
                pool = (list(R.BOOL_SETTINGS) + list(R.CHOICE_SETTINGS)
                        + list(R.NUMBER_SETTINGS))
                best = None
                for setting in pool:
                    aliases = [str(n).lower() for n in (setting.names or ())]
                    if any(words == alias or words in alias or alias in words
                           for alias in aliases):
                        best = best or setting
                return best
            sa = sa or fuzzy(a)
            sb = sb or fuzzy(b)
        if sa is None or sb is None:
            return Result("I could not find two settings in that sentence to compare, "
                          "so I will not guess. Say both names as they appear in "
                          "Settings and I will read their current values.",
                          "area_overview")
        va = R.current_value(sa)
        vb = R.current_value(sb)
        same = (str(getattr(sa, "section", "") or getattr(sa, "where", ""))
                == str(getattr(sb, "section", "") or getattr(sb, "where", "")))
        head = (str(sa.names[0]) + " is " + (va or "unreadable") + " and "
                + str(sb.names[0]) + " is " + (vb or "unreadable") + ". ")
        if same:
            return Result(head + "They are in the same area, so they interact - "
                          "change one at a time and watch the other; each change asks "
                          "its own card where it needs one, and the change journal "
                          "records what moved.", "area_overview")
        return Result(head + "They are in different areas and do not overwrite each "
                      "other; each change asks its own card where it needs one.",
                      "area_overview")
    words = _awareness_area_words(area)
    if words:
        return Result(words, "area_overview")
    return Result("I could not read an area called that, so I will not guess. The "
                  "areas with several switches are: learning, manner, notifications, "
                  "voices, web-search, second-card, big-model and security - ask about "
                  "one of those and I will read every part it holds.", "area_overview")


def _run_preset_current() -> Result:
    """Which preset is ACTIVE, its model, context, measured speed and how to switch."""
    import jarvis_presets as P
    try:
        pid = str(P.choice() or "")
    except Exception:
        pid = ""
    row = _preset_row(pid) or {}
    if not pid:
        return Result("I cannot read which preset is chosen on this PC right now, so I "
                      "will not name one. Say \"use the Coding preset\" to choose "
                      "one; that asks one card first.", "preset_current")
    title = str(row.get("title") or pid)
    model = str(row.get("model") or _model_record() or "")
    try:
        context = _how_context_words()
    except Exception:
        context = ""
    try:
        speed = _how_fast_words()
    except Exception:
        speed = ""
    said = 'I am on the "' + title + '" preset'
    if model:
        said += ", running " + model
    said += ". " + context
    if speed:
        said += " " + speed
    said += (' To change it, say "use the <name> preset" - that asks one card '
             "before anything switches, and the change is recorded in my change "
             "journal.")
    return Result(said, "preset_current")


def _bench_state_path() -> str:
    return os.path.join(_awareness_dir(), "bench-run.json")


def _bench_progress_snapshot():
    try:
        with open(_bench_state_path(), encoding="utf-8") as fh:
            return json.loads(fh.read())
    except Exception:
        return None


def _run_bench_history() -> Result:
    """The benchmark rows this PC recorded, newest first, or an honest empty."""
    try:
        import jarvis_bench as B
        rows = list(B.BenchLog().runs(limit=5))
    except Exception:
        rows = []
    if not rows:
        return Result("I have no benchmark runs recorded on this PC yet. Brain, "
                      "Model, Models runs one, and since today I can start one for "
                      'the current model if you say "run a benchmark".',
                      "bench_history")
    bits = []
    for row in rows:
        model = str(row.get("model") or "a model")
        lane = str(row.get("lane") or "")
        speed = row.get("gen_median")
        try:
            speed_s = (f"{float(speed):.1f} tokens a second"
                       if speed is not None else "no speed number")
        except (TypeError, ValueError):
            speed_s = "no speed number"
        said = model + (" on the " + lane + " lane" if lane else "") + " - " + speed_s
        if row.get("spilled"):
            said += " (some layers spilled)"
        if row.get("ok") is False:
            said += " (that run failed)"
        bits.append(said)
    return Result("The newest benchmark runs on this PC: " + "; ".join(bits)
                  + '. Ask "run a benchmark" to measure the current model again.',
                  "bench_history")


def _run_bench_run() -> Result:
    """Start ONE async benchmark of the current model through jarvis_bench itself."""
    import jarvis_bench as B
    model = _model_record() or ""
    if not model:
        try:
            import jarvis_presets as P
            model = str((_preset_row(str(P.choice() or "")) or {}).get("model") or "")
        except Exception:
            model = ""
    if not model:
        return Result("Nothing was measured: I cannot read which model is running on "
                      "this PC right now, and I will not guess one.", "bench_run")
    lane = "everyday"
    try:
        import jarvis_presets as P
        pid = str(P.choice() or "").lower()
    except Exception:
        pid = ""
    if "coding" in pid:
        lane = "coding"
    body = {"model": model, "lane": lane,
            "confirm": {"model": model, "lane": lane, "may_evict": True}}
    try:
        code, out = B.start(body)
    except Exception as exc:                       # noqa: BLE001 - said plainly
        return Result(f"Nothing was measured: the benchmark runner could not start "
                      f"({type(exc).__name__}).", "bench_run")
    out = out if isinstance(out, dict) else {}
    if code != 200:
        said = str(out.get("error") or out.get("sentence") or "the run was refused")
        return Result("Nothing was measured: " + said.rstrip(".") + ".",
                      "bench_run")
    run_id = str(out.get("run_id") or "")
    try:
        os.makedirs(_awareness_dir(), exist_ok=True)
        with open(_bench_state_path(), "w", encoding="utf-8") as fh:
            json.dump({"run_id": run_id, "model": model, "lane": lane,
                       "kind": "speed", "at": int(time.time())}, fh)
    except Exception:
        pass
    said = (f"Measuring {model} now on the {lane} lane - run {run_id}. "
            "Nothing else should use the model until it finishes. Ask \"how is the "
            'benchmark going?" and I will tell you.')
    note = str(out.get("message") or "")
    if note and "Nothing else" not in note:
        said += " " + note
    return Result(said, "bench_run")


def _run_bench_suites() -> Result:
    """Start ONE five-suite run of the current model through jarvis_bench itself.

    The five suites are the owner's ask of 2026-11-07 (speed, coding, general,
    tool-calling, vision). The run happens on the throwaway model server, never
    on the live lanes; an owner run may pause the lane it needs and jarvis_bench
    warms the active preset back afterwards. The model is read from the same
    record the speed bench uses, never guessed.
    """
    import jarvis_bench as B
    model = _model_record() or ""
    if not model:
        try:
            import jarvis_presets as P
            model = str((_preset_row(str(P.choice() or "")) or {}).get("model") or "")
        except Exception:
            model = ""
    if not model:
        return Result("Nothing was measured: I cannot read which model is running on "
                      "this PC right now, and I will not guess one.", "bench_suites")
    lane = "everyday"
    try:
        import jarvis_presets as P
        pid = str(P.choice() or "").lower()
    except Exception:
        pid = ""
    if "coding" in pid:
        lane = "coding"
    body = {"model": model, "lane": lane, "mode": "owner",
            "confirm": {"model": model, "lane": lane, "may_evict": True}}
    try:
        code, out = B.start_suites(body)
    except Exception as exc:                       # noqa: BLE001 - said plainly
        return Result(f"Nothing was measured: the suite runner could not start "
                      f"({type(exc).__name__}).", "bench_suites")
    out = out if isinstance(out, dict) else {}
    if code != 200:
        said = str(out.get("error") or out.get("sentence") or "the run was refused")
        return Result("Nothing was measured: " + said.rstrip(".") + ".",
                      "bench_suites")
    run_id = str(out.get("run_id") or "")
    try:
        os.makedirs(_awareness_dir(), exist_ok=True)
        with open(_bench_state_path(), "w", encoding="utf-8") as fh:
            json.dump({"run_id": run_id, "model": model, "lane": lane,
                       "kind": "suites", "at": int(time.time())}, fh)
    except Exception:
        pass
    return Result(
        f"Started the five-suite benchmark on {model}: speed, coding, general, "
        "tool-calling and vision. A model that cannot see pictures skips the "
        "vision suite and says so; nothing is counted as a pass that was skipped. "
        "It runs on a throwaway model server and may pause the lane it needs, then "
        "put the active preset back. Ask \"how is the benchmark going?\" for "
        "progress and the numbers when it finishes.", "bench_suites")


def _run_bench_progress() -> Result:
    state = _bench_progress_snapshot()
    if not state:
        return Result("I have no benchmark run in progress and none recorded from "
                      'this chat. Say "run a benchmark" and I will measure the '
                      "current model.", "bench_progress")
    run_id = str(state.get("run_id") or "")
    kind = str(state.get("kind") or "speed")
    try:
        import jarvis_bench as B
        code, out = (B.suite_view(run_id) if kind == "suites" else B.view(run_id))
    except Exception as exc:                       # noqa: BLE001 - said plainly
        return Result(f"I cannot read that benchmark run right now "
                      f"({type(exc).__name__}).", "bench_progress")
    out = out if isinstance(out, dict) else {}
    if code != 200:
        return Result("I cannot read that benchmark run: "
                      + str(out.get("error") or "it is unknown to this PC") + ".",
                      "bench_progress")
    st = str(out.get("state") or "")
    if st == "running":
        return Result(f"The benchmark is running: step {out.get('step')} of "
                      f"{out.get('of')} for {state.get('model') or 'the current model'}. "
                      "I will have the numbers when it finishes.", "bench_progress")
    if st == "failed":
        return Result("That benchmark run failed: "
                      + str(out.get("why") or "no reason was recorded") + ".",
                      "bench_progress")
    result = out.get("result") or {}
    words = str(result.get("words") or "") if isinstance(result, dict) else ""
    if words:
        return Result(words, "bench_progress")
    return Result("The benchmark finished. " + json.dumps(result)[:400],
                  "bench_progress")


def _run_bench_stop() -> Result:
    state = _bench_progress_snapshot()
    if not state:
        return Result("There is no benchmark run from this chat to stop.",
                      "bench_stop")
    run_id = str(state.get("run_id") or "")
    kind = str(state.get("kind") or "speed")
    try:
        import jarvis_bench as B
        code, out = (B.cancel_suite(run_id) if kind == "suites" else B.cancel(run_id))
    except Exception as exc:                       # noqa: BLE001 - said plainly
        return Result(f"I could not stop it ({type(exc).__name__}).", "bench_stop")
    out = out if isinstance(out, dict) else {}
    said = str(out.get("words") or out.get("message") or out.get("error") or "")
    return Result(said or ("Stopped the benchmark run." if code == 200 else
                           "I could not stop that benchmark run."), "bench_stop")


def _run_self_changes(f: dict) -> Result:
    """What changed about this PC's Jarvis, from the local change journal."""
    _awareness_note()
    rows = _awareness_journal_rows()
    when = str(f.get("when") or "").lower()
    now = time.time()
    cutoff = 0
    if "today" in when:
        cutoff = now - 86400
    elif "yesterday" in when:
        cutoff = now - 2 * 86400
    elif "last" in when:
        cutoff = now - 7 * 86400
    rows = [r for r in rows if int(r.get("at") or 0) >= cutoff]
    if not rows:
        said = ("Nothing has changed since I started keeping this record"
                + (" in that window" if cutoff else "") + ".")
    else:
        bits = []
        for row in rows[-6:]:
            changes = row.get("changed") or []
            if not changes:
                continue
            parts = []
            for change in changes[:6]:
                key = str(change.get("key") or "")
                old = change.get("from")
                new = change.get("to")
                if key.startswith("setting:"):
                    parts.append(f"{key[8:]} went from {old} to {new}")
                elif key.startswith("tool:"):
                    parts.append(f"the {key[5:]} tool switch went from {old} to {new}")
                elif key == "preset":
                    parts.append(f"the preset went from {old} to {new}")
                elif key == "model":
                    parts.append(f"the running model went from {old} to {new}")
                elif key == "version":
                    parts.append(f"Jarvis updated from {old} to {new}")
                elif key.startswith("count:"):
                    parts.append(f"{key[6:]} went from {old} to {new}")
                else:
                    parts.append(f"{key} went from {old} to {new}")
            when_s = time.strftime("%H:%M on %d %b",
                                   time.localtime(int(row.get("at") or now)))
            bits.append(when_s + ": " + "; ".join(parts))
        said = "What changed, newest last: " + " | ".join(bits) + "."
    try:
        import jarvis_recent_changes as RC
        bullets = list(getattr(RC, "BULLETS", ()) or ())
        if bullets:
            said += (" The newest item on the record of shipped changes is: "
                     + str(bullets[0]) + ".")
    except Exception:
        pass
    return Result(said, "self_changes")


def _preset_count() -> int:
    """How many presets `/api/presets` serves, from the module that owns them.

    `jarvis_presets.py` exposes its rows as the module constant `PRESETS` (the
    tuple `/api/presets` renders through `P.view()`); it has NO `presets()`
    helper. Asking `hasattr(P, "presets")` for one made the live answer say
    "switch between 0 presets" while the route served 9 (Wave-8.2 deploy
    finding 1, 2026-11-07). This reads the real collection and counts it, and
    falls back to the view only if a future module renames the constant. A PC
    without the module answers 0 rather than a guess.
    """
    try:
        import jarvis_presets as P
        rows = getattr(P, "PRESETS", None)
        if rows is None:
            view = P.view() or {}
            rows = view.get("presets") or view.get("rows") or ()
        return len(rows or ())
    except Exception:                   # noqa: BLE001 - older PC: no module
        return 0


def _run_self_inventory() -> Result:
    """What the program HAS, counted from its own registries."""
    counts = []
    try:
        import jarvis_feature_catalogue as C
        counts.append(f"{len(C.FEATURES)} features in the feature list")
    except Exception:
        pass
    try:
        import jarvis_settings_registry as R
        counts.append(f"{len(R.BOOL_SETTINGS) + len(R.CHOICE_SETTINGS) + len(R.NUMBER_SETTINGS)} settings")
        counts.append(f"{len(R.tool_targets())} tools I can offer the AI model")
    except Exception:
        pass
    try:
        counts.append(f"{_preset_count()} presets")
    except Exception:
        pass
    try:
        import jarvis_model_knowledge as K
        models = K.installed_models() or []
        counts.append(f"{len(models)} local models installed")
    except Exception:
        pass
    version = ""
    try:
        version = str((_read_version_source() or {}).get("version") or "")
    except Exception:
        version = ""
    said = "I have " + ", ".join(counts) + "."
    if version:
        said = f"I am backend {version}, and I have " + ", ".join(counts) + "."
    said += (' Ask "what can you change?" for the things you control from here, or '
             '"what tools do you have?" for the tool switches.')
    return Result(said, "self_inventory")


def _run_changeable_overview() -> Result:
    """Every kind of thing the owner can change from chat/Live."""
    import jarvis_settings_registry as R
    tools = len(R.tool_targets())
    settings = (len(R.BOOL_SETTINGS) + len(R.CHOICE_SETTINGS)
                + len(R.NUMBER_SETTINGS))
    presets = _preset_count()
    said = (f"I can change {settings} settings and {tools} tool switches, switch "
            f"between {presets} presets, switch or install a local model, change "
            "what needs an approval card, allow apps on your phone, connect "
            "accounts, add or remove plug-ins and skills, and change my manner "
            "and personality - through chat or Jarvis Live, the same way. ")
    said += ("A change that matters asks one card before it happens and is recorded "
             'in my change journal; reads and answers never do. Examples: "turn on '
             'background learning", "set the personality to advocate", "use the '
             'Coding preset", "which tools are on?", "what changed about you?".')
    return Result(said, "changeable_overview")


def _run_tool_switches_on_off(f: dict) -> Result:
    import jarvis_settings_registry as R
    want = str(f.get("want") or "")
    on, off, err = [], [], []
    for tool, names in R.tool_targets().items():
        try:
            value = R.reading_tool_now(tool)
        except Exception:
            err.append(tool)
            continue
        label = str((names or (tool,))[0])
        (on if value else off).append(label)
    if want == "on":
        if not on:
            return Result("Every tool switch is OFF right now, so the AI model is "
                          "offered none of them.", "tool_switches_on_off")
        return Result("On right now: " + ", ".join(sorted(on)) + ".",
                      "tool_switches_on_off")
    if want == "off":
        if not off:
            return Result("Every tool switch is ON right now.", "tool_switches_on_off")
        return Result("Off right now: " + ", ".join(sorted(off)) + ".",
                      "tool_switches_on_off")
    return Result(f"{len(on)} on, {len(off)} off"
                  + (f", {len(err)} unreadable" if err else "")
                  + '. Ask "which tools are on?" or "which tools are off?" for the '
                  "names.", "tool_switches_on_off")


def _run_tool_switch_state(f: dict) -> Result:
    import jarvis_settings_registry as R
    tool = str(f.get("tool") or "")
    names = R.tool_targets().get(tool) or (tool,)
    label = str(names[0])
    try:
        value = R.reading_tool_now(tool)
    except Exception:
        value = None
    state = "on" if value else "off"
    other = "off" if value else "on"
    return Result(f"The {label} switch is {state} right now. Say \"turn {other} "
                  f"{label}\" to change it - an ON change asks one card plus Windows "
                  f"Hello on this PC; OFF is instant. Say \"tell me about {label}\" "
                  "for what it does.", "tool_switch_state")


def _run_desktop_row_info(f: dict) -> Result:
    """One desktop Settings-page row, explained by name, with its current value."""
    import jarvis_settings_registry as R
    name = str(f.get("name") or "").strip().lower()
    if not name:
        return Result("Which setting? Say the words on the Settings page and I will "
                      "read it for you.", "desktop_row_info")
    row = None
    for candidate in R.SETTINGS_ROWS:
        if str(candidate.label or "").strip().lower() == name:
            row = candidate
            break
    if row is None:
        for candidate in R.SETTINGS_ROWS:
            if name and name in str(candidate.label or "").strip().lower():
                row = candidate
                break
    if row is None:
        return Result("I could not find a Settings-page row with those words, so I "
                      'will not guess. Ask "what settings do you have?" for the '
                      "areas, or name a switch.", "desktop_row_info")
    said = '"' + str(row.label) + '": ' + (row.detail.strip()
                                           or "no detail line on the page.")
    if row.setting:
        setting = None
        for candidate in (list(R.BOOL_SETTINGS) + list(R.CHOICE_SETTINGS)
                          + list(R.NUMBER_SETTINGS)):
            if str(getattr(candidate, "key", "")) == str(row.setting):
                setting = candidate
                break
        value = R.current_value(setting) if setting is not None else None
        if value:
            said += f" Right now it is {value}."
        said += " You can change it by asking me, or on the Settings page."
    else:
        said += (" This one is changed on the Settings page only (it has no spoken "
                 "adjust), in the " + str(row.section) + " area"
                 + (f", row {row.order}" if row.order else "") + ".")
    return Result(said, "desktop_row_info")


def _run_setting_named_read(f: dict) -> Result:
    """A named setting's current value, and how to change it."""
    import jarvis_settings_registry as R
    name = str(f.get("name") or "").strip()
    setting = None
    for finder in (R.find_bool_setting, R.find_choice_setting,
                   R.find_bool_setting_words, R.find_choice_setting_words):
        try:
            setting = finder(name)
        except Exception:
            setting = None
        if setting is not None:
            break
    if setting is None:
        return Result("I could not find a setting with those words, so I will not "
                      'guess. Ask "what settings do you have?" for the areas.',
                      "setting_named_read")
    value = R.current_value(setting)
    label = str(setting.names[0])
    where = str(getattr(setting, "section", "") or getattr(setting, "where", "") or "")
    said = label + " is " + (value or "unreadable right now")
    if where:
        said += " (the " + where.replace("-", " ") + " area)"
    said += "."
    if hasattr(setting, "on_word"):
        said += f' To change it say "{label} on" or "{label} off"'
    else:
        said += f' To change it say "set {label} to <one of its values>"'
    said += "; a change that needs a card asks one first."
    return Result(said, "setting_named_read")


def _awareness_chat(s: str, text: str) -> Optional[Intent]:
    """The full self-awareness sentences, matched before the older lanes."""
    low = str(s or "").strip()
    if not low or len(low) > 400:
        return None
    raw = " ".join(str(text or "").strip().split())
    if _AW_FOLDER_LIST.fullmatch(raw) or _AW_FOLDER_LIST.fullmatch(low):
        return Intent("folder_list")
    m = _AW_FOLDER_ADD.fullmatch(raw)
    if m is not None:
        words = (m.groupdict().get("p1") or m.groupdict().get("p2")
                 or m.groupdict().get("p3") or "").strip()
        target = _folder_path_from_words(words)
        if target:
            return Intent("folder_add", {"path": target})
        return Intent("folder_add", {"ask": True, "words": words})

    if _AW_PRESET_CURRENT.fullmatch(low):
        return Intent("preset_current")
    if _AW_BENCH_SUITES.fullmatch(low):
        return Intent("bench_suites")
    if _AW_BENCH_RUN.fullmatch(low):
        return Intent("bench_run")
    if _AW_BENCH_PROGRESS.fullmatch(low):
        return Intent("bench_progress")
    if _AW_BENCH_STOP.fullmatch(low):
        return Intent("bench_stop")
    if _AW_BENCH_HISTORY.fullmatch(low):
        return Intent("bench_history")
    m = _AW_CHANGES.fullmatch(low)
    if m:
        d = m.groupdict()
        return Intent("self_changes", {"when": (d.get("when") or d.get("when2") or "")})
    if _AW_CHANGEABLE.fullmatch(low):
        return Intent("changeable_overview")
    if _AW_INVENTORY.fullmatch(low):
        return Intent("self_inventory")
    if _AW_TOOL_LIST.fullmatch(low):
        if re.search(r"\b(?:off|disabled|turned\s+off)\b", low):
            want = "off"
        elif re.search(r"\b(?:on|enabled|turned\s+on)\b", low):
            want = "on"
        else:
            want = ""
        return Intent("tool_switches_on_off", {"want": want})
    m = _AW_TOOL_STATE.fullmatch(low)
    if m:
        import jarvis_settings_registry as R
        words = (m.groupdict().get("name") or m.groupdict().get("name2") or "").strip()
        words = re.sub(r"^(?:the|my|your)\s+", "", words)
        words = re.sub(r"\s+(?:tool|switch)$", "", words)
        tool = R.find_tool_target(words)
        if tool:
            return Intent("tool_switch_state", {"tool": tool})
    m = _AW_DESKTOP_ROW.fullmatch(low)
    if m:
        import jarvis_settings_registry as R
        words = (m.groupdict().get("name") or m.groupdict().get("name2")
                 or m.groupdict().get("name3") or "").strip()
        words = re.sub(r"^(?:the|my|your)\s+", "", words)
        # The older explain door keeps a sentence it can answer ("how do i
        # change auto adjust" is its own per-device answer, not a page row).
        try:
            if R.find_explain_setting(words) is not None:
                return None
        except Exception:
            pass
        for candidate in R.SETTINGS_ROWS:
            label = str(candidate.label or "").strip().lower()
            if label and (words == label or (len(words) >= 4 and words in label)):
                return Intent("desktop_row_info", {"name": words})
    m = _AW_SETTING_READ.fullmatch(low)
    if m:
        import jarvis_settings_registry as R
        words = (m.groupdict().get("name") or m.groupdict().get("name2") or "").strip()
        words = re.sub(r"^(?:the|my|your)\s+", "", words)
        setting = None
        for finder in (R.find_bool_setting, R.find_choice_setting,
                       R.find_bool_setting_words, R.find_choice_setting_words):
            try:
                setting = finder(words)
            except Exception:
                setting = None
            if setting is not None:
                break
        if setting is not None:
            # The older NAMED explain door owns a setting it already knows
            # (`setting_explain`), and it must keep it: this new answer is the
            # fallback for a setting that door cannot resolve (the Wave-8.2 gap
            # was one learning switch). Never steal a sentence it answers.
            try:
                if R.find_explain_setting(words) is not None:
                    return None
            except Exception:
                pass
            return Intent("setting_named_read", {"name": words})
    m = _AW_AREA.fullmatch(low)
    if m:
        d = m.groupdict()
        if d.get("a") and d.get("b"):
            return Intent("area_overview", {"a": d["a"].strip(), "b": d["b"].strip()})
        area = (d.get("area") or d.get("area2") or "").strip()
        if area:
            return Intent("area_overview", {"area": area})
    return None
